def walk_and_list(base_path, depth=0):
    indent = "  " * depth
    skipped = {'kernel-venv', 'lib64', 'site-packages', 'bin'}

    items = []
    for item in os.listdir(base_path):
        full_path = os.path.join(base_path, item)
        if any(s in item.lower() for s in skipped):
            continue
        if os.path.isfile(full_path):
            items.append(f"{indent}{item}")
        elif os.path.isdir(full_path):
            items.append(f"{indent}{item}/")
            sub_items = walk_and_list(full_path, depth+1)
            for sub in sub_items[:3]:
                items.append(sub)
            if len([x for x in items if indent == "  " * depth]) > 15:
                break

    return items

